options.styles:
& {
.gw-cards { display: flex; flex-wrap: wrap; align-items: stretch; gap: 12px; }
.gw-card { position: relative; width: 244px; min-height: 150px; padding: 16px 18px 14px; border: 1px solid var(--grafana-border-color-weak, rgba(128, 128, 128, 0.35)); border-radius: 8px; background: var(--grafana-background-secondary, transparent); }
.gw-good { border-top: 3px solid #70c1b3; }
.gw-mixed { border-top: 3px solid #ffe066; }
.gw-poor { border-top: 3px solid #f25f5c; }
.gw-score { font-size: 32px; font-weight: 600; line-height: 1.1; letter-spacing: -0.5px; }
.gw-good .gw-score { color: #70c1b3; }
.gw-mixed .gw-score { color: #ffe066; }
.gw-poor .gw-score { color: #f25f5c; }
.gw-name { margin-top: 8px; font-size: 18px; font-weight: 600; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.gw-sub { margin-top: 2px; font-size: 12px; opacity: 0.65; }
.gw-pop { display: none; position: absolute; top: 0; left: 0; right: 0; bottom: 0; z-index: 10; padding: 10px 14px; border-radius: 7px; background: var(--grafana-background-primary, #161616); overflow: hidden; }
.gw-card:hover .gw-pop { display: block; }
.gw-pop-h { font-size: 12px; font-weight: 600; margin-bottom: 4px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.gw-pop-t { width: 100%; border-collapse: collapse; }
.gw-pop-t td { padding: 1px 0; font-size: 11px; line-height: 1.4; }
.gw-pop-t td:first-child { opacity: 0.65; padding-right: 10px; white-space: nowrap; }
.gw-pop-t td:last-child { text-align: right; }
}
